MinimalModel.CanonicalDivisor.mk.congr_s.type:
∀ {k : Type u} [inst : Field k] {X : MinimalModel.NormalVariety k} (K K_1 : MinimalModel.Divisor ℤ X) (e_K : K = K_1)
  (ω ω_1 : MinimalModel.TopForm X) (e_ω : ω = ω_1) (isDiv : MinimalModel.IsDivOfForm K ω),
  { K := K, ω := ω, isDiv := isDiv } = { K := K_1, ω := ω_1, isDiv := ⋯ }

MinimalModel.CanonicalDivisor.mk.inj.type:
∀ {k : Type u} {inst : Field k} {X : MinimalModel.NormalVariety k} {K : MinimalModel.Divisor ℤ X}
  {ω : MinimalModel.TopForm X} {isDiv : MinimalModel.IsDivOfForm K ω} {K_1 : MinimalModel.Divisor ℤ X}
  {ω_1 : MinimalModel.TopForm X} {isDiv_1 : MinimalModel.IsDivOfForm K_1 ω_1},
  { K := K, ω := ω, isDiv := isDiv } = { K := K_1, ω := ω_1, isDiv := isDiv_1 } → K = K_1 ∧ ω = ω_1

MinimalModel.ExtremalFace.isFace.type:
∀ {k : Type u} [inst : Field k] {X : MinimalModel.NormalVariety k} {I : MinimalModel.IntersectionData X}
  (self : MinimalModel.ExtremalFace I) (a b : MinimalModel.CurveSpace X),
  a ∈ I.coneOfCurves → b ∈ I.coneOfCurves → a + b ∈ self.carrier → a ∈ self.carrier ∧ b ∈ self.carrier

MinimalModel.ExtremalFace.mk.inj.type:
∀ {k : Type u} {inst : Field k} {X : MinimalModel.NormalVariety k} {I : MinimalModel.IntersectionData X}
  {carrier : PointedCone ℝ (MinimalModel.CurveSpace X)} {le : carrier ≤ I.coneOfCurves}
  {isFace :
    ∀ (a b : MinimalModel.CurveSpace X),
      a ∈ I.coneOfCurves → b ∈ I.coneOfCurves → a + b ∈ carrier → a ∈ carrier ∧ b ∈ carrier}
  {carrier_1 : PointedCone ℝ (MinimalModel.CurveSpace X)} {le_1 : carrier_1 ≤ I.coneOfCurves}
  {isFace_1 :
    ∀ (a b : MinimalModel.CurveSpace X),
      a ∈ I.coneOfCurves → b ∈ I.coneOfCurves → a + b ∈ carrier_1 → a ∈ carrier_1 ∧ b ∈ carrier_1},
  { carrier := carrier, le := le, isFace := isFace } = { carrier := carrier_1, le := le_1, isFace := isFace_1 } →
    carrier = carrier_1

MinimalModel.IntersectionData.mk.inj.type:
∀ {k : Type u} {inst : Field k} {X : MinimalModel.NormalVariety k}
  {dot : MinimalModel.Divisor ℝ X → MinimalModel.Curve X → ℝ}
  {dot_cartier :
    ∀ (D : MinimalModel.Divisor ℤ X),
      MinimalModel.IsCartier D →
        ∀ (C : MinimalModel.Curve X), ∃ d, MinimalModel.IsIntersectionNumber D C d ∧ dot D.toReal C = ↑d}
  {dot_add :
    ∀ (D D' : MinimalModel.Divisor ℝ X),
      MinimalModel.IsRCartier D →
        MinimalModel.IsRCartier D' → ∀ (C : MinimalModel.Curve X), dot (D + D') C = dot D C + dot D' C}
  {dot_smul :
    ∀ (r : ℝ) (D : MinimalModel.Divisor ℝ X),
      MinimalModel.IsRCartier D → ∀ (C : MinimalModel.Curve X), dot (r • D) C = r * dot D C}
  {finiteDim : FiniteDimensional ℝ ↥(Submodule.span ℝ (Set.range fun C D => dot (↑D) C))}
  {dot_1 : MinimalModel.Divisor ℝ X → MinimalModel.Curve X → ℝ}
  {dot_cartier_1 :
    ∀ (D : MinimalModel.Divisor ℤ X),
      MinimalModel.IsCartier D →
        ∀ (C : MinimalModel.Curve X), ∃ d, MinimalModel.IsIntersectionNumber D C d ∧ dot_1 D.toReal C = ↑d}
  {dot_add_1 :
    ∀ (D D' : MinimalModel.Divisor ℝ X),
      MinimalModel.IsRCartier D →
        MinimalModel.IsRCartier D' → ∀ (C : MinimalModel.Curve X), dot_1 (D + D') C = dot_1 D C + dot_1 D' C}
  {dot_smul_1 :
    ∀ (r : ℝ) (D : MinimalModel.Divisor ℝ X),
      MinimalModel.IsRCartier D → ∀ (C : MinimalModel.Curve X), dot_1 (r • D) C = r * dot_1 D C}
  {finiteDim_1 : FiniteDimensional ℝ ↥(Submodule.span ℝ (Set.range fun C D => dot_1 (↑D) C))},
  { dot := dot, dot_cartier := dot_cartier, dot_add := dot_add, dot_smul := dot_smul, finiteDim := finiteDim } =
      { dot := dot_1, dot_cartier := dot_cartier_1, dot_add := dot_add_1, dot_smul := dot_smul_1,
        finiteDim := finiteDim_1 } →
    dot = dot_1

MinimalModel.MMPStepData.mk.inj.type:
∀ {k : Type u} {inst : Field k} {A B : MinimalModel.PairModel k} {Z : MinimalModel.NormalVariety k}
  {f : A.X.toScheme ⟶ Z.toScheme} {g : B.X.toScheme ⟶ Z.toScheme}
  {over_f : CategoryTheory.CategoryStruct.comp f Z.str = A.X.str}
  {over_g : CategoryTheory.CategoryStruct.comp g Z.str = B.X.str} {contraction_f : MinimalModel.IsContraction f}
  {birational_f : MinimalModel.IsBirationalHom f} {extremal : MinimalModel.IsExtremalContraction A.I f}
  {negative : MinimalModel.IsRAmpleOver (-A.P.KΔ) f} {contraction_g : MinimalModel.IsContraction g}
  {small_g : MinimalModel.IsSmallHom g} {positive : MinimalModel.IsRAmpleOver B.P.KΔ g}
  {strict : MinimalModel.IsStrictTransform A B f g} {Z_1 : MinimalModel.NormalVariety k}
  {f_1 : A.X.toScheme ⟶ Z_1.toScheme} {g_1 : B.X.toScheme ⟶ Z_1.toScheme}
  {over_f_1 : CategoryTheory.CategoryStruct.comp f_1 Z_1.str = A.X.str}
  {over_g_1 : CategoryTheory.CategoryStruct.comp g_1 Z_1.str = B.X.str}
  {contraction_f_1 : MinimalModel.IsContraction f_1} {birational_f_1 : MinimalModel.IsBirationalHom f_1}
  {extremal_1 : MinimalModel.IsExtremalContraction A.I f_1} {negative_1 : MinimalModel.IsRAmpleOver (-A.P.KΔ) f_1}
  {contraction_g_1 : MinimalModel.IsContraction g_1} {small_g_1 : MinimalModel.IsSmallHom g_1}
  {positive_1 : MinimalModel.IsRAmpleOver B.P.KΔ g_1} {strict_1 : MinimalModel.IsStrictTransform A B f_1 g_1},
  { Z := Z, f := f, g := g, over_f := over_f, over_g := over_g, contraction_f := contraction_f,
        birational_f := birational_f, extremal := extremal, negative := negative, contraction_g := contraction_g,
        small_g := small_g, positive := positive, strict := strict } =
      { Z := Z_1, f := f_1, g := g_1, over_f := over_f_1, over_g := over_g_1, contraction_f := contraction_f_1,
        birational_f := birational_f_1, extremal := extremal_1, negative := negative_1,
        contraction_g := contraction_g_1, small_g := small_g_1, positive := positive_1, strict := strict_1 } →
    Z = Z_1 ∧ f ≍ f_1 ∧ g ≍ g_1

MinimalModel.NormalVariety.mk.inj.type:
∀ {k : Type u} {inst : Field k} {toScheme : AlgebraicGeometry.Scheme} {str : toScheme ⟶ AlgebraicGeometry.Spec ↧k}
  {isIntegral : AlgebraicGeometry.IsIntegral toScheme} {isSeparated : AlgebraicGeometry.IsSeparated str}
  {locallyOfFiniteType : AlgebraicGeometry.LocallyOfFiniteType str} {compactSpace : CompactSpace ↥toScheme}
  {isLocallyNoetherian : AlgebraicGeometry.IsLocallyNoetherian toScheme}
  {isNormal : MinimalModel.IsNormalScheme toScheme} {toScheme_1 : AlgebraicGeometry.Scheme}
  {str_1 : toScheme_1 ⟶ AlgebraicGeometry.Spec ↧k} {isIntegral_1 : AlgebraicGeometry.IsIntegral toScheme_1}
  {isSeparated_1 : AlgebraicGeometry.IsSeparated str_1}
  {locallyOfFiniteType_1 : AlgebraicGeometry.LocallyOfFiniteType str_1} {compactSpace_1 : CompactSpace ↥toScheme_1}
  {isLocallyNoetherian_1 : AlgebraicGeometry.IsLocallyNoetherian toScheme_1}
  {isNormal_1 : MinimalModel.IsNormalScheme toScheme_1},
  { toScheme := toScheme, str := str, isIntegral := isIntegral, isSeparated := isSeparated,
        locallyOfFiniteType := locallyOfFiniteType, compactSpace := compactSpace,
        isLocallyNoetherian := isLocallyNoetherian, isNormal := isNormal } =
      { toScheme := toScheme_1, str := str_1, isIntegral := isIntegral_1, isSeparated := isSeparated_1,
        locallyOfFiniteType := locallyOfFiniteType_1, compactSpace := compactSpace_1,
        isLocallyNoetherian := isLocallyNoetherian_1, isNormal := isNormal_1 } →
    toScheme = toScheme_1 ∧ str ≍ str_1

MinimalModel.Pair.mk.inj.type:
∀ {k : Type u} {inst : Field k} {X : MinimalModel.NormalVariety k} {K : MinimalModel.CanonicalDivisor X}
  {Δ : MinimalModel.Divisor ℝ X} {nonneg : 0 ≤ Δ} {rCartier : MinimalModel.IsRCartier (K.K.toReal + Δ)}
  {K_1 : MinimalModel.CanonicalDivisor X} {Δ_1 : MinimalModel.Divisor ℝ X} {nonneg_1 : 0 ≤ Δ_1}
  {rCartier_1 : MinimalModel.IsRCartier (K_1.K.toReal + Δ_1)},
  { K := K, Δ := Δ, nonneg := nonneg, rCartier := rCartier } =
      { K := K_1, Δ := Δ_1, nonneg := nonneg_1, rCartier := rCartier_1 } →
    K = K_1 ∧ Δ = Δ_1

MinimalModel.PairModel.mk.inj.type:
∀ {k : Type u} {inst : Field k} {X : MinimalModel.NormalVariety k} {P : MinimalModel.Pair X}
  {I : MinimalModel.IntersectionData X} {projective : MinimalModel.IsProjective X} {X_1 : MinimalModel.NormalVariety k}
  {P_1 : MinimalModel.Pair X_1} {I_1 : MinimalModel.IntersectionData X_1}
  {projective_1 : MinimalModel.IsProjective X_1},
  { X := X, P := P, I := I, projective := projective } = { X := X_1, P := P_1, I := I_1, projective := projective_1 } →
    X = X_1 ∧ P ≍ P_1 ∧ I ≍ I_1

MinimalModel.Program.mk.inj.type:
∀ {k : Type u} {inst : Field k} {A : MinimalModel.PairModel k} {len : ℕ∞} {model : ℕ → MinimalModel.PairModel k}
  {start : model 0 = A} {step : ∀ (i : ℕ), ↑i < len → MinimalModel.IsMMPStep (model i) (model (i + 1))} {len_1 : ℕ∞}
  {model_1 : ℕ → MinimalModel.PairModel k} {start_1 : model_1 0 = A}
  {step_1 : ∀ (i : ℕ), ↑i < len_1 → MinimalModel.IsMMPStep (model_1 i) (model_1 (i + 1))},
  { len := len, model := model, start := start, step := step } =
      { len := len_1, model := model_1, start := start_1, step := step_1 } →
    len = len_1 ∧ model = model_1

MinimalModel.Toric.Fan.WallData.mk.inj.type:
∀ {n : ℕ} {F : MinimalModel.Toric.Fan n} {σ σ' : PointedCone ℝ (MinimalModel.Toric.NR n)} {ray : F.Ray}
  {ray_le : ↑ray ≤ σ'} {ray_not_le : ¬↑ray ≤ σ} {eq_or_le : ∀ (ρ : F.Ray), ↑ρ ≤ σ' → ρ = ray ∨ ↑ρ ≤ σ}
  {base : Finset F.Ray} {base_le : ∀ ρ ∈ base, ↑ρ ≤ σ} {coeff : F.Ray → ℝ}
  {relation : MinimalModel.Toric.toNR (F.generator ray) = ∑ ρ ∈ base, coeff ρ • MinimalModel.Toric.toNR (F.generator ρ)}
  {ray_1 : F.Ray} {ray_le_1 : ↑ray_1 ≤ σ'} {ray_not_le_1 : ¬↑ray_1 ≤ σ}
  {eq_or_le_1 : ∀ (ρ : F.Ray), ↑ρ ≤ σ' → ρ = ray_1 ∨ ↑ρ ≤ σ} {base_1 : Finset F.Ray} {base_le_1 : ∀ ρ ∈ base_1, ↑ρ ≤ σ}
  {coeff_1 : F.Ray → ℝ}
  {relation_1 :
    MinimalModel.Toric.toNR (F.generator ray_1) = ∑ ρ ∈ base_1, coeff_1 ρ • MinimalModel.Toric.toNR (F.generator ρ)},
  { ray := ray, ray_le := ray_le, ray_not_le := ray_not_le, eq_or_le := eq_or_le, base := base, base_le := base_le,
        coeff := coeff, relation := relation } =
      { ray := ray_1, ray_le := ray_le_1, ray_not_le := ray_not_le_1, eq_or_le := eq_or_le_1, base := base_1,
        base_le := base_le_1, coeff := coeff_1, relation := relation_1 } →
    ray = ray_1 ∧ base = base_1 ∧ coeff = coeff_1

MinimalModel.Toric.Fan.mk.inj.type:
∀ {n : ℕ} {cones : Set (PointedCone ℝ (MinimalModel.Toric.NR n))} {finite : cones.Finite}
  {rational : ∀ σ ∈ cones, MinimalModel.Toric.IsRationalPolyhedral σ}
  {stronglyConvex : ∀ σ ∈ cones, MinimalModel.Toric.IsStronglyConvex σ}
  {face_mem : ∀ σ ∈ cones, ∀ (τ : PointedCone ℝ (MinimalModel.Toric.NR n)), τ.IsFaceOf σ → τ ∈ cones}
  {inter_face : ∀ σ ∈ cones, ∀ τ ∈ cones, (σ ⊓ τ).IsFaceOf σ} {cones_1 : Set (PointedCone ℝ (MinimalModel.Toric.NR n))}
  {finite_1 : cones_1.Finite} {rational_1 : ∀ σ ∈ cones_1, MinimalModel.Toric.IsRationalPolyhedral σ}
  {stronglyConvex_1 : ∀ σ ∈ cones_1, MinimalModel.Toric.IsStronglyConvex σ}
  {face_mem_1 : ∀ σ ∈ cones_1, ∀ (τ : PointedCone ℝ (MinimalModel.Toric.NR n)), τ.IsFaceOf σ → τ ∈ cones_1}
  {inter_face_1 : ∀ σ ∈ cones_1, ∀ τ ∈ cones_1, (σ ⊓ τ).IsFaceOf σ},
  { cones := cones, finite := finite, rational := rational, stronglyConvex := stronglyConvex, face_mem := face_mem,
        inter_face := inter_face } =
      { cones := cones_1, finite := finite_1, rational := rational_1, stronglyConvex := stronglyConvex_1,
        face_mem := face_mem_1, inter_face := inter_face_1 } →
    cones = cones_1

MinimalModel.Toric.IsLatticeBasis.repr_e.type:
∀ {n : ℕ} {κ : Type u_1} [inst : Fintype κ] {v : Fin n → ℤ} {u : κ → Fin n → ℤ}
  (h : MinimalModel.Toric.IsLatticeBasis (Option.elim' v u)) (a₀ : ℤ) (a : κ → ℤ),
  ⇑(h.basis.repr (a₀ • v + ∑ i, a i • u i)) = Option.elim' a₀ a

MinimalModel.Toric.P2.degree_wallData.type:
∀ {σ σ' : PointedCone ℝ (MinimalModel.Toric.NR 2)} {a b c : MinimalModel.Toric.P2.fan.Ray} {hab : a ≠ b} {hc' : ↑c ≤ σ'}
  {hc : ¬↑c ≤ σ} {heq : ∀ (ρ : MinimalModel.Toric.P2.fan.Ray), ↑ρ ≤ σ' → ρ = c ∨ ↑ρ ≤ σ} {ha : ↑a ≤ σ} {hb : ↑b ≤ σ}
  {hrel :
    MinimalModel.Toric.toNR (MinimalModel.Toric.P2.fan.generator c) =
      -1 • MinimalModel.Toric.toNR (MinimalModel.Toric.P2.fan.generator a) +
        -1 • MinimalModel.Toric.toNR (MinimalModel.Toric.P2.fan.generator b)}
  (D : MinimalModel.Toric.P2.fan.TDivisor ℝ),
  (MinimalModel.Toric.P2.wallData a b c hab hc' hc heq ha hb hrel).degree D = D a + D b + D c

MinimalModel.centreMorphism_closedPoint.type:
